C++.fragment:
template<typename T> T head(const std::vector<T>& xs) { return xs[0]; }
auto a = head(std::vector<int>{4, 5, 6});
auto b = head(std::vector<std::string>{"p", "q"});
std::string result = std::to_string(a) + b;

Go.fragment:
func head[T any](xs []T) T {
 return xs[0]
}
a := head([]int{4, 5, 6})
b := head([]string{"p", "q"})
result := strconv.Itoa(a) + b

Java.fragment:
static <T> T head(List<T> xs) { return xs.get(0); }
int a = head(List.of(4, 5, 6));
String b = head(List.of("p", "q"));
String result = Integer.toString(a) + b;

Rust.fragment:
fn head<T: Copy>(xs: &[T]) -> T { xs[0] }
let a = head(&[4, 5, 6]);
let b = head(&["p", "q"]);
format!("{}{}", a, b)

Swift.fragment:
func head<T>(_ xs: [T]) -> T { return xs[0] }
let a = head([4, 5, 6])
let b = head(["p", "q"])
return "\(a)" + b

TypeScript.fragment:
function head<T>(xs: T[]): T { return xs[0]; }
const a = head([4, 5, 6]);
const b = head(["p", "q"]);
return `${a}${b}`;

Zig.fragment:
fn head(comptime T: type, xs: []const T) T { return xs[0]; }
const a = head(i32, .{4,5,6});
const b = head([]const u8, .{"p","q"});
